from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,os
import pandas as pd
O=Path(__file__).resolve().parent;BASE=O.parents[1];R=Path(os.environ.get('FINANCETHESIS_REPO','/Users/ludviguvang/dev/financethesis'))
paths={'roles':BASE/'omxsb_scaled_round_20261103/independent_design/retention/FROZEN_ROLES.csv','events':R/'output/omxsb_replication_2007/events_car.csv','panel':R/'data/raw/lseg/panel_2005_2026/stocks_daily_2005.parquet','index':R/'data/raw/lseg/panel_2005_2026/indices_daily (1).csv','roster':R/'output/omxsb_open_questions_20261102/eligibility/dated_stockholm_instrument_roster.csv','cancel':R/'output/omxsb_execution_followup_20261102/sources/known_cancellations.csv','anchors':BASE/'volume_units_full_20261102/all_available_exactISIN_month_anchors.csv','CA':R/'output/omxsb_extension_20261031/ownership/corporate_action_sources.csv'}
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
lock={'created_utc':datetime.now(timezone.utc).isoformat(),'outcomes_computed':False,'source_spec_sha256':sha(O/'SOURCE_GATE_SPEC.txt'),'inputs':{k:{'path':str(p),'sha256':sha(p)}for k,p in paths.items()}}
(O/'SOURCE_GATE_LOCK.json').write_text(json.dumps(lock,indent=2)+'\n')
S=pd.read_csv(paths['roles'],usecols=['event_id','review','type','role','ric','nasdaq_isin']);assert len(S)==280 and S.event_id.nunique()==70 and S.review.nunique()==10
E=pd.read_csv(paths['events'],usecols=['event_id','RIC','AD','ED'],parse_dates=['AD','ED']);S=S.merge(E[['event_id','AD','ED']],on='event_id',validate='m:1');assert S.AD.notna().all()
I=pd.read_csv(paths['index'],usecols=['ric','date','close']);I.date=pd.to_datetime(I.date);cal=pd.DatetimeIndex(sorted(I.loc[I.ric.isin(['.OMXSBGI','.OMXSPI'])&I.close.gt(0),'date'].unique()));ix={d:i for i,d in enumerate(cal)}
P=pd.read_parquet(paths['panel'],columns=['ric','date','volume','turnover','source'],filters=[('ric','in',sorted(S.ric.unique()))]);P.date=pd.to_datetime(P.date);assert not P.duplicated(['ric','date']).any()
U=pd.read_csv(paths['roster'],usecols=['isin','month','currency','source_url','source_excel_row']);K=pd.read_csv(paths['cancel']);A=pd.read_csv(paths['anchors'],usecols=['RIC','month','anchor_basic_valid','source_url']);CA=pd.read_csv(paths['CA'],parse_dates=['action_date'])
rows=[]
for z in S.itertuples():
 a=ix[z.AD];e=ix[z.ED];be=min(a-12,e-23);bi=cal[be-49:be+1];wi=cal[e-22:e+23];assert len(bi)==50 and len(wi)==45 and bi.max()<wi.min() and bi.max()<z.AD
 p=P[P.ric.eq(z.ric)].set_index('date');b=p.reindex(bi);w=p.reindex(wi);year=int(z.review[:4]);month=year*100+(4 if z.review.endswith('H1') else 10);u=U[U['isin'].eq(z.nasdaq_isin)&U.month.eq(month)];curr=sorted(set(u.currency.dropna().astype(str)));ca=CA[CA.RIC.eq(z.ric)&CA.action_date.between(bi.min(),wi.max())]
 r={'event_id':z.event_id,'review':z.review,'role':z.role,'ric':z.ric,'nasdaq_isin':z.nasdaq_isin,'AD':str(z.AD.date()),'ED':str(z.ED.date()),'baseline_start':str(bi.min().date()),'baseline_end':str(bi.max().date()),'window_start':str(wi.min().date()),'window_end':str(wi.max().date()),'baseline_all_source_tr':bool(b.source.eq('tr').all()),'window_all_source_tr':bool(w.source.eq('tr').all()),'dated_currency':';'.join(curr),'dated_currency_unique_SEK':curr==['SEK'],'dated_roster_rows':len(u),'has_existing_any_month_unit_anchor':bool(A.RIC.eq(z.ric).any()),'has_known_CA_in_measurement_span':len(ca)>0,'known_CA_kinds':';'.join(sorted(set(ca.kind))),'known_cancelled_control':z.role!='event'and bool((K.review.eq(z.review)&K.RIC.eq(z.ric)).any())}
 for f in ['volume','turnover']:
  bv=pd.to_numeric(b[f],errors='coerce');wv=pd.to_numeric(w[f],errors='coerce')
  r[f+'_baseline_present']=int(bv.notna().sum());r[f+'_window_present']=int(wv.notna().sum());r[f+'_baseline_nonnegative']=bool(bv.ge(0).all());r[f+'_window_nonnegative']=bool(wv.ge(0).all());r[f+'_baseline_has_positive']=bool(bv.gt(0).any());r[f+'_presence_pass']=all([r[f+'_baseline_present']==50,r[f+'_window_present']==45,r[f+'_baseline_nonnegative'],r[f+'_window_nonnegative'],r[f+'_baseline_has_positive'],r['baseline_all_source_tr'],r['window_all_source_tr'],not r['known_cancelled_control']])
 rows.append(r)
Q=pd.DataFrame(rows);Q.to_csv(O/'ROLE_SOURCE_PRESENCE.csv',index=False)
G=Q.groupby(['event_id','review']).agg(volume_presence_pass=('volume_presence_pass','all'),turnover_presence_pass=('turnover_presence_pass','all'),all_dated_currency_SEK=('dated_currency_unique_SEK','all'),any_known_CA=('has_known_CA_in_measurement_span','any'),all_roles_have_any_old_unit_anchor=('has_existing_any_month_unit_anchor','all')).reset_index();G.to_csv(O/'EVENT_SOURCE_PRESENCE.csv',index=False)
s={'outcomes_computed':False,'events':70,'roles':280,'reviews':10,'unique_RIC':S.ric.nunique(),'unique_review_RIC':len(S[['review','ric']].drop_duplicates()),'volume_presence_pass_events':int(G.volume_presence_pass.sum()),'turnover_presence_pass_events':int(G.turnover_presence_pass.sum()),'turnover_presence_and_dated_SEK_events':int((G.turnover_presence_pass&G.all_dated_currency_SEK).sum()),'events_all_roles_have_any_old_anchor':int(G.all_roles_have_any_old_unit_anchor.sum()),'role_currency_counts':Q.dated_currency.value_counts().to_dict(),'events_known_CA':int(G.any_known_CA.sum()),'known_cancelled_control_roles':int(Q.known_cancelled_control.sum()),'per_review':G.groupby('review').agg(events=('event_id','size'),volume_pass=('volume_presence_pass','sum'),turnover_pass=('turnover_presence_pass','sum'),all_SEK=('all_dated_currency_SEK','sum')).reset_index().to_dict('records'),'limitation':'Presence and reference-date currency only; not full daily unit or venue certification. No volume-window total/mean/ratio or price outcome read.'};(O/'SOURCE_PRESENCE_SUMMARY.json').write_text(json.dumps(s,indent=2)+'\n');print(json.dumps(s,indent=2))
